/**
 * One way to put a photo on the public site.
 *
 * Renders <picture> with AVIF and WebP srcsets when the image has them (generated by
 * `npm run images`), an optional art-directed crop for phones, explicit width and
 * height (no layout shift), lazy loading by default, and eager + high fetch priority
 * for the page's main (LCP) image only.
 */
export interface ResponsiveSource {
  /** URL used by <img src>: a JPEG (generated set) or a single WebP (placeholders). */
  fallback: string;
  /** srcset strings, e.g. "a-640.avif 640w, a-960.avif 960w". */
  avif?: string;
  webp?: string;
  jpeg?: string;
  width: number;
  height: number;
  alt: string;
  /** True while the slot still holds a temporary, unlicensed image. */
  placeholder?: boolean;
}

interface ResponsiveImageProps {
  image: ResponsiveSource;
  /** Overrides image.alt. Pass "" for purely decorative images. */
  alt?: string;
  /** How wide the image is drawn, for the browser to pick a size, e.g. "(min-width: 1024px) 50vw, 100vw". */
  sizes?: string;
  /** The page's main image: loads immediately with high priority. Use once per page. */
  priority?: boolean;
  /** Different crop for phones (shown below 768px). */
  mobile?: ResponsiveSource;
  className?: string;
  imgClassName?: string;
}

const MOBILE = "(max-width: 767px)";

export function ResponsiveImage({ image, alt, sizes = "100vw", priority = false, mobile, className, imgClassName }: ResponsiveImageProps) {
  return (
    <picture className={className}>
      {mobile && (
        <>
          {mobile.avif && <source media={MOBILE} type="image/avif" srcSet={mobile.avif} sizes="100vw" width={mobile.width} height={mobile.height} />}
          {mobile.webp && <source media={MOBILE} type="image/webp" srcSet={mobile.webp} sizes="100vw" width={mobile.width} height={mobile.height} />}
          <source media={MOBILE} srcSet={mobile.jpeg ?? mobile.fallback} sizes="100vw" width={mobile.width} height={mobile.height} />
        </>
      )}
      {image.avif && <source type="image/avif" srcSet={image.avif} sizes={sizes} />}
      {image.webp && <source type="image/webp" srcSet={image.webp} sizes={sizes} />}
      <img
        src={image.fallback}
        srcSet={image.jpeg}
        sizes={image.jpeg ? sizes : undefined}
        alt={alt ?? image.alt}
        width={image.width}
        height={image.height}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding={priority ? "sync" : "async"}
        className={imgClassName}
      />
    </picture>
  );
}
